import{_ as o,o as a,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const c=JSON.parse('{"title":"第 9 章 写文档：报告、方案与白皮书（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第9章 写文档：报告、方案与白皮书（易懂版）.md","filePath":"easy/第9章 写文档：报告、方案与白皮书（易懂版）.md"}'),s={name:"easy/第9章 写文档：报告、方案与白皮书（易懂版）.md"};function n(l,t,i,h,d,u){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-9-章-写文档-报告、方案与白皮书-易懂版" tabindex="-1">第 9 章 写文档：报告、方案与白皮书（易懂版） <a class="header-anchor" href="#第-9-章-写文档-报告、方案与白皮书-易懂版" aria-label="Permalink to &quot;第 9 章 写文档：报告、方案与白皮书（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 9 章 写文档：报告、方案与白皮书（完整版）](../../bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 9 章 写文档：报告、方案与白皮书.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>写报告、方案、说明书——AI 最拿手的事，但要用对姿势。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>写作就像&quot;点菜后厨做菜&quot;：<strong>你给菜谱（要求），我负责炒（写）</strong>。但菜好不好吃，取决于你菜谱给得细不细，以及我炒完你要<strong>尝一口（检查）</strong>。</p><h2 id="核心就-3-件事" tabindex="-1">核心就 3 件事 <a class="header-anchor" href="#核心就-3-件事" aria-label="Permalink to &quot;核心就 3 件事&quot;">​</a></h2><ol><li><strong>先定框架再动笔</strong>：写之前先定结构——给谁看、什么结论、分几部分。框架对了，内容不会散。</li><li><strong>给足&quot;食材&quot;</strong>：相关素材、数据、背景资料越全，写得越扎实；<strong>别只给一句话就让我编</strong>。</li><li><strong>写三遍</strong>：第一遍出骨架，第二遍填血肉，第三遍改语气——<strong>别指望一遍到位</strong>。</li></ol><h2 id="文档写作四步法" tabindex="-1">文档写作四步法 <a class="header-anchor" href="#文档写作四步法" aria-label="Permalink to &quot;文档写作四步法&quot;">​</a></h2><ol><li><strong>定读者</strong>：给老板看？给同事看？给客户看？语气差很多；</li><li><strong>定结论</strong>：最想表达的那句话是什么？放最前面（先结论后论证）；</li><li><strong>给素材</strong>：把相关文件、数据都指给我；</li><li><strong>要修改</strong>：第一稿出来后，圈出不满意的部分，让我改到你要的样子。</li></ol><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p><strong>指令</strong>：&quot;写一份 2 页的月度报告：读者是部门主管，先讲 3 个成果，再讲 1 个问题，最后给下周计划。素材在 <code>数据</code> 文件夹里。&quot;</p><p><strong>你会看到</strong>：我先列个提纲给你 → 你确认 → 我写成文 → 你圈出要改的 → 我改到好。</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ &quot;帮我写个方案&quot;——<strong>方案给谁、解决啥、有啥限制</strong>，全没说；</li><li>❌ 第一稿就惊艳——<strong>写好文档的秘诀是&quot;改&quot;</strong>，不是&quot;一次成&quot;；</li><li>❌ 数据靠我编——<strong>数字必须你给</strong>，我只能整理，不能凭空造。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>写文档 = 定读者 + 定结论 + 给素材 + 反复改。</strong> 四步走完，文档像样。</p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>下次要写东西前，先口头回答三个问题：<strong>给谁看？核心结论？素材在哪？</strong> 答完再让我写。</p><p>👉 [下一章：写代码，脚本、修改与调试（易懂版）](第10章 写代码：脚本、修改与调试（易懂版）.md)</p>',19)])])}const g=o(s,[["render",n]]);export{c as __pageData,g as default};
